"""Low level user interaction functions for the VolumeView Reconstruction window. Used by the VolumeViewReconstructionObjects page object class"""

from .objects.xvi_volume_view_reconstruction_objects import VolumeViewReconstructionObjects
from interops.libraries.squish_actions import CommonActions
import interops.libraries.desktop.decorators as deco
from interops.libraries.squish_actions.constants import XVI_REGISTRATION_APP_NAME # Note: VolumeView Reconstruction window uses the same AUT name as Registration window

def __find_main_volume_view_reconstruction_window(timeout: int=3000):
    """Searches for the main VolumeView Reconstruction window. Returns True if successfully located.

    -> Hidden function that should not be used outside the context of the volume_view_reconstruction_functions.py file

    :param int timeout: Time to wait for the main reconstruction window object to be found
    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.find_object(VolumeViewReconstructionObjects.main_Volume_View_Reconstruction_Window, timeout) is not None else False

def __find_volume_view_reconstruction_approval_dialog():
    """Searches for the Reconstruction Approval Dialog. Returns True if successfully located.

    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.find_object(VolumeViewReconstructionObjects.volume_View_Reconstruction_Approval_Window) is not None else False

@deco.set_separate_app_context(application_name=XVI_REGISTRATION_APP_NAME)
def wait_for_volume_view_reconstruction_pane(wait_timeout: int) -> bool:
    """Waits for the main VolumeView Reconstruction pane to exist. Returns True if successfully located.
    """
    return True if CommonActions.wait_for_object_exists(VolumeViewReconstructionObjects.volume_View_Reconstruction_Pane, wait_timeout) is not None else False


# ------------------------------- VolumeView Reconstruction Review (bottom pane) and Approval dialog interactions -------------------------------

@deco.set_separate_app_context(application_name=XVI_REGISTRATION_APP_NAME)
def click_volume_view_reconstruction_accept_button() -> None:
    """Locates the main VolumeView Reconstruction window > then left mouse click on the main Accept button only if its enabled
    """
    if __find_main_volume_view_reconstruction_window():
        CommonActions.left_click_object_no_move(VolumeViewReconstructionObjects.volume_View_Reconstruction_Review_Accept_Button)

@deco.set_separate_app_context(application_name=XVI_REGISTRATION_APP_NAME)
def click_volume_view_reconstruction_dismiss_button() -> None:
    """Locates the main VolumeView Reconstruction window > then left mouse click on the main Dismiss button only if its enabled
    """
    if __find_main_volume_view_reconstruction_window():
        CommonActions.left_click_object_no_move(VolumeViewReconstructionObjects.volume_View_Reconstruction_Review_Dismiss_Button)

@deco.set_separate_app_context(application_name=XVI_REGISTRATION_APP_NAME)
def edit_volume_view_reconstruction_approval_comment_field(valueToSet: str) -> None:
    """Locates the main VolumeView Reconstruction and Approval windows > then enters the specified text

    :param str valueToSet: Initial or Comment text string to be entered
    """
    if __find_volume_view_reconstruction_approval_dialog():
        CommonActions.type_in_textfield(VolumeViewReconstructionObjects.volume_View_Reconstruction_Approval_Field, valueToSet)

@deco.set_separate_app_context(application_name=XVI_REGISTRATION_APP_NAME)
def click_volume_view_reconstruction_approval_ok_button() -> None:
    """Locates the main VolumeView Reconstruction and Approval windows > then left mouse click on the OK button only if its enabled
    """
    if __find_volume_view_reconstruction_approval_dialog():
        CommonActions.left_click_object_no_move(VolumeViewReconstructionObjects.volume_View_Reconstruction_Approval_Ok_Button)

@deco.set_separate_app_context(application_name=XVI_REGISTRATION_APP_NAME)
def click_volume_view_reconstruction_approval_cancel_button() -> None:
    """Locates the main VolumeView Reconstruction and Approval windows > then left mouse click on the Cancel button only if its enabled
    """
    if __find_volume_view_reconstruction_approval_dialog():
        CommonActions.left_click_object_no_move(VolumeViewReconstructionObjects.volume_View_Reconstruction_Approval_Cancel_Button)
